# DeepKids content for NCERT EVS "Our Wondrous World", Classes 3–5 (DeepKids Levels 3–5).
# "covers" is drawn from the chapter title and secondary summaries; align with the official book before publishing.
# Each chapter: covers, game (name, story + play), experiments, activities, project (with what you end up with),
# reading (real books; check availability), links (other NCERT books, same class), dk (DeepKids Plus topics).

C = {}
def ch(cls, n, **k): C[(cls, n)] = k

# ---------------- Class 3 (Level 3, age 8) ----------------
ch(3, 1, covers="Kinds of families, relatives and what we call them, roles and shared work at home, friends, generations then and now.",
   game=("Relation Railway", "A train leaves 'Me Station' and only correct relations can board. Take turns reading riddle cards ('Your father's sister's son is your…'). Answer in 10 seconds to add a coach to your train; a wrong answer derails it. Longest train wins. Bonus coach for saying the word in a third language."),
   exp=["Hand-span survey: measure the hand span and height of everyone in the family (and a neighbour family). Chart it: do children's hands grow toward their parents' sizes?"],
   act=["Then-and-Now interview with a grandparent: games, school, food, toys at age 8.", "Chore wheel: list every job at home, see who does it, rotate jobs for one week and talk about how it felt."],
   proj=("Family Museum Box", "Over 2 weeks collect 5 objects with family stories (an old photo, a utensil, a letter), label each, add a family tree and a recorded elder interview.", "A shoebox museum the child presents to the family"),
   read=["Grandma's Bag of Stories, Sudha Murty", "The Family Book, Todd Parr"],
   links=["Santoor Ch 3: Best Friends", "Veena Ch 7: मित्र को पत्र", "Maths Mela Ch 4: Vacation with My Nani Maa"], dk=["B2", "C6"])
ch(3, 2, covers="Village fairs: stalls, crafts, toys and rides, buying and selling, crowds and staying safe.",
   game=("Mela Market", "You each run a stall (bangles, chaat, toys) with ₹100 in play coins. Draw customer cards with wishes and budgets; sell, give exact change, restock. Surprise cards: 'Lost at the mela: what do you do?' (answer well to earn a coin). First to ₹150 wins."),
   exp=["Firki lab: make paper pinwheels with 4, 6 and 8 blades. Which spins fastest in front of a fan? Does blade size matter?", "Lattu test: spin a top on floor, steel plate and carpet. Time each spin. What slows it down?"],
   act=["Draw a map of a mela (real or remembered) with stalls, entry, rides and a 'meeting point if lost'.", "Make a traditional toy: a dugdugi (pellet drum) from a paper cup or a chakri."],
   proj=("Our Mini Mela", "Plan and run a small mela for family or neighbours: 3 stalls, handmade toys, price list, a money log, and a lost-and-found rule.", "A real event, plus a chart of what sold and what was earned"),
   read=["StoryWeaver (Pratham Books): search 'mela' for free picture books"],
   links=["Maths Mela Ch 14: The Surajkund Fair", "Maths Mela Ch 12: Give and Take"], dk=["B2", "B6"])
ch(3, 3, covers="Festivals across India, why they happen when they do (harvests, seasons, the Moon), foods, lights, sharing and celebrating together.",
   game=("Festival Calendar Race", "A circle of 12 months on the floor. Draw festival cards (Pongal, Bihu, Onam, Eid, Diwali, Christmas, Baisakhi, Holi, Durga Puja, Gurpurab, Phooldei…). Place each in its month and say why it falls then: harvest, season or Moon. Correct month 1 point, correct reason 2 points, naming the Moon's phase that night 3 points."),
   exp=["Haldi magic: paint with haldi paste, then dab soap water on it. Why does yellow turn red? (Haldi is a natural indicator.)", "Diya and jar: which burns longer, a diya under a small glass or under a big jar? (Adult lights it.)"],
   act=["Festival food map of India: one dish per festival, pinned on a map.", "Mark the next 3 months' full and new moons and find which festivals land on them."],
   proj=("A Festival of Our Own", "Design a new family festival for this season: what it celebrates, food, decorations, a song, an invitation. Host it.", "A celebration, an invitation card and photos"),
   read=["Binny's Diwali, Thrity Umrigar", "Lights for Gita, Rachna Gilmore", "Amma, Tell Me About Diwali!, Bhakti Mathur"],
   links=["Veena Ch 9: प्रकृति पर्व – फूलदेई", "Maths Mela Ch 7: Raksha Bandhan", "Santoor Ch 11: Chanda Mama Counts the Stars"], dk=["B2", "B5"])
ch(3, 4, covers="Kinds of plants (trees, shrubs, herbs, climbers), parts and their jobs, leaf shapes, seeds, what plants need, how we use plants.",
   game=("Leaf Detective Bingo", "Bingo cards show leaf shapes, edges and vein patterns (heart, needle, toothed, compound, parallel veins). On a 20-minute walk, mark a square only when you hold a matching leaf. First line shouts 'Leaf!'. Final round: 'Which part do we eat?' speed quiz with carrot, potato, spinach, cauliflower, rice."),
   exp=["Coloured-water flower: put a white flower or celery stalk in water with food colour. Check after 6 and 24 hours. How did the colour climb?", "Seeds' needs: sow moong in four cups (water + light, no water, dark, cold fridge). Compare after 5 days."],
   act=["Leaf-rubbing book: 10 leaves, crayon rubbings, names in two languages.", "Adopt a tree: measure its trunk with string, sketch it, visit monthly."],
   proj=("Kitchen-Garden Pot", "Sow methi or dhaniya, water and measure daily, harvest at about 4 weeks, and cook something with it.", "A harvest, a growth chart and a dish"),
   read=["From Seed to Plant, Gail Gibbons", "The Tiny Seed, Eric Carle", "A Seed Is Sleepy, Dianna Hutts Aston"],
   links=["Veena Ch 5: आम का पेड़", "Veena Ch 13: पेड़ों की अम्मा 'तिमक्का'", "Santoor Ch 4: Out in the Garden"], dk=["A5"])
ch(3, 5, covers="Homes and habitats, how plants and animals depend on each other: food, shelter, pollination and seed spreading.",
   game=("Web of Life", "Lay 12 living-thing cards on a table (neem tree, bee, myna, earthworm, cow, grass, frog, snake, child…). Take turns joining two with a string and saying how one depends on the other. Then draw a 'Gone!' card: remove that being and every string tied to it. Who is left standing? Rebuild with a rescue plan."),
   exp=["Seed hitchhikers: wear old socks over shoes and walk through grass, then 'plant' the sock in a tray of soil and water it. What grows?", "Be a bee: dab a cotton bud in one flower and touch another. Look with a magnifier at the pollen."],
   act=["Minibeast hunt under a flowerpot or stone (put everything back).", "Bird-feeder log: who visits, when, what do they eat?"],
   proj=("Wildlife-Friendly Corner", "Set up a water bowl, a feeder, a flowering plant and a bamboo 'insect hotel' on a balcony or garden; keep a 3-week visitor log.", "A working mini habitat and a visitor chart"),
   read=["Over and Under the Pond, Kate Messner", "Up in the Garden and Down in the Dirt, Kate Messner", "What Do You Do With a Tail Like This?, Steve Jenkins & Robin Page"],
   links=["Veena Ch 4: बया हमारी चिड़िया रानी!", "Veena Ch 2: चींटी", "Veena Ch 3: कितने पैर?", "Santoor Ch 2: Badal and Moti"], dk=["A5", "B4", "B9"])
ch(3, 6, covers="Living peacefully with people and nature: sharing, solving quarrels, caring for animals and surroundings.",
   game=("Harmony Village", "A cooperative game: you both win or lose together. Each round flip a Trouble card (the pond is dirty, friends are quarrelling, a stray dog is hungry, a tree will be cut). Spend your action tokens on fixes and explain your fix to earn a bonus. Keep the Harmony meter above zero for 10 rounds to win."),
   exp=["Noise map: rate the noise in 6 places (kitchen, road, park, temple, bedroom at night) from 1 to 5, or use a phone sound meter. Where do birds sing most?"],
   act=["Quarrel-fix role play: act out three common fights and try three ways to solve each.", "Ask neighbours how they share water, parking or a park. Draw what you learn."],
   proj=("Harmony Pact", "Family and child pick one action for 2 weeks (water bowls for street animals, a peace corner, a sharing shelf) and keep a log.", "A pact poster and a 2-week log"),
   read=["The Curious Garden, Peter Brown", "Wangari's Trees of Peace, Jeanette Winter", "Have You Filled a Bucket Today?, Carol McCloud"],
   links=["Veena Ch 18: हम अनेक किंतु एक", "Veena Ch 12: अपना-अपना काम", "Santoor Ch 8: Thank God"], dk=["B9", "C4", "B2"])
ch(3, 7, covers="Where water comes from, how we use it, clean and dirty water, saving water, traditional ways of storing rainwater.",
   game=("Drop Detective", "Each player starts the day with 50 water-drop tokens. Draw activity cards (brushing with the tap running −6, mug bath −15, shower −40, washing a car with a pipe −60) and choose the wiser way where you can. Leak cards hit everyone. The player with the most drops at bedtime wins."),
   exp=["Bottle filter: layer gravel, sand, charcoal and cotton in a cut bottle and pour muddy water through. Clearer, but is it safe to drink? (No, it still needs boiling.)", "Sun vs shade: equal water in two plates. Which dries first, and where did the water go?"],
   act=["Home water audit: count mugs and buckets used in one day.", "Find out how a stepwell, lake or tank near you stored water."],
   proj=("Rain Catcher", "Make a rain gauge and a rain-collecting container; record rainfall and use the water for plants.", "A working gauge, a collector and a rainfall chart"),
   read=["The Water Princess, Susan Verde", "Water Is Water, Miranda Paul", "A Drop Around the World, Barbara McKinney"],
   links=["Santoor Ch 6: Paper Boats", "Maths Mela Ch 11: Filling and Lifting"], dk=["B8", "A4"])
ch(3, 8, covers="Where food comes from, foods of different regions, cooking, sharing meals, eating well.",
   game=("Thali Builder", "Food cards carry energy, body-building and protective icons. Race to build a balanced thali from your hand; then a twist card asks for a Kerala, Punjabi or Bengali thali using only local foods. Opponent can challenge a card's region."),
   exp=["Starch test: a drop of iodine (Betadine) on potato, rice, bread and cucumber. Which turn blue-black? (Adult; don't eat after.)", "Sprouting chana: weigh 50 g, soak and sprout for 2 days, weigh again. Why heavier?"],
   act=["Food-origin trail: pick 5 foods at dinner and trace each back to a farm, a tree or an animal.", "Cook a grandparent's recipe together and write it down."],
   proj=("Our Family Cookbook", "Collect 5 recipes from relatives with where each comes from, photos, and one dish the child cooks.", "A handmade or printed recipe booklet"),
   read=["Gregory, the Terrible Eater, Mitchell Sharmat", "Eating the Alphabet, Lois Ehlert"],
   links=["Santoor Ch 7: The Big Laddoo", "Veena Ch 6: बीरबल की खिचड़ी", "Veena Ch 14: किसान की होशियारी", "Maths Mela Ch 10: Fun at Class Party!"], dk=["C11"])
ch(3, 9, covers="Keeping clean, eating, sleeping and playing well, feelings, staying happy.",
   game=("Germ Busters", "A race track of daily-life squares. Habit squares (washed hands, played outside, slept on time) push you ahead; Germ squares send you back unless you hold a Shield card, which you earn by acting out a healthy habit. First to Bedtime wins."),
   exp=["Glitter germs: glitter on hands, shake hands, then wash with water only vs soap. What's left?", "Heartbeat: count your pulse for 15 seconds, do 30 jumps, count again."],
   act=["Feelings charades: act out happy, worried, angry, proud; others guess and share when they felt it.", "A one-week sleep and play diary."],
   proj=("7-Day Healthy Me Challenge", "Track water, sleep, outdoor play, fruit and one kind act each day.", "A completed challenge chart and a reflection drawing"),
   read=["Germs Are Not for Sharing, Elizabeth Verdick", "The Busy Body Book, Lizzy Rockwell", "The Color Monster, Anna Llenas"],
   links=["Veena Ch 10: रस्साकशी"], dk=["C10", "C7"])
ch(3, 10, covers="Objects around us and what they are made of, natural vs human-made materials, properties like hard, soft, waterproof, magnetic.",
   game=("Material Top Trumps", "Make 20 cards of household objects and score each for hardness, bendiness, waterproofness and floating. Each turn, pick a property from your top card; the higher score wins both cards. Test any disputed score for real before deciding."),
   exp=["Raincoat test: drip water on paper, plastic, cotton, wool and foil. Which keep a tissue underneath dry?", "Magnet hunt: which things in the house does a magnet pick up? Are all metals magnetic?"],
   act=["'Made of what?' house hunt: find 5 things each of wood, metal, plastic, glass, cloth and clay.", "Old vs new: compare a clay pot and a plastic bottle for keeping water cool."],
   proj=("Material Museum", "Collect, test and label 20 materials with their properties and uses.", "A museum display the child guides visitors through"),
   read=["The Way Things Work Now, David Macaulay (for parent and child together)"],
   links=["Santoor Ch 5: Talking Toys", "Veena Ch 11: एक जादुई पिटारा", "Maths Mela Ch 2: Toy Joy"], dk=["A4", "A3"])
ch(3, 11, covers="How things are made by hand and by machine, artisans and their tools, turning old things into new.",
   game=("Inventor's Workshop", "Draw a challenge card ('A bridge that holds 10 coins using only 2 sheets of paper', 'A boat that carries 5 marbles from foil') and a 10-minute timer. Build, test, and score: did it work, how many coins or marbles, how few materials. Swap roles as judge."),
   exp=["Paper strength: flat paper vs folded zig-zag vs rolled tube. How many coins can each hold as a bridge?", "Clay drying: make two small pots, dry one in sun and one in shade. Which cracks?"],
   act=["Meet an artisan (potter, carpenter, tailor) or watch one at work; list their tools.", "Make a toy from trash using an Arvind Gupta design."],
   proj=("Design, Build, Improve", "Build a working toy (a balloon car or a spinning top), test it, improve it 3 times and record what changed.", "A working toy and an improvement log"),
   read=["Rosie Revere, Engineer, Andrea Beaty", "The Most Magnificent Thing, Ashley Spires", "Iggy Peck, Architect, Andrea Beaty"],
   links=["Santoor Ch 6: Paper Boats", "Maths Mela Ch 5: Fun with Shapes"], dk=["A4", "B6"])
ch(3, 12, covers="Kinds of waste, sorting at home, composting, reducing, reusing and recycling, where waste goes.",
   game=("Bin Blitz", "60 seconds on the clock. Flip picture cards and slap each onto the right bin: wet, dry, hazardous, e-waste. Trick cards (a tetra pack, a battery, a used tea bag) are worth double. Beat your last score."),
   exp=["Bury test: bury a banana peel, a paper, a cotton rag and a plastic bag in a pot of soil. Dig up after 3 weeks.", "Start a compost pot with kitchen peels and dry leaves; check its warmth and smell weekly."],
   act=["Weigh one day's home waste and sort it.", "Visit or talk to a kabadiwala: what can they sell, what can't they?"],
   proj=("Zero-Waste Week", "Weigh waste for a normal week, then a week of family changes; compare.", "Compost, a before-and-after chart and a family pledge"),
   read=["One Plastic Bag, Miranda Paul", "Why Should I Recycle?, Jen Green", "The Adventures of a Plastic Bottle, Alison Inches"],
   links=[], dk=["B10"])

# ---------------- Class 4 (Level 4, age 9) ----------------
