   game=("Food Chain Dominoes", "Each domino has an eater on one half and something eaten on the other, from Indian ecosystems (grass–deer–tiger, plankton–fish–kingfisher, leaf–caterpillar–myna). Match ends to build the longest chain; a 'Decomposer' tile can join any dead end."),
   exp=["Camouflage hunt: scatter 20 green and 20 red paper 'insects' on grass. A partner 'bird' has 30 seconds to pick as many as possible. Which colour survives? Repeat on red soil."],
   act=["Nature-trail bingo walk.", "Sketch 10 living things in a field journal with where you found them."],
   proj=("Biodiversity Count", "Mark a 1 m × 1 m square with string in a park or garden; visit weekly for 4 weeks and record every plant and animal.", "A mini field guide to your square"),
