# ---------------- Class 5 (Level 5, age 10) ----------------
ch(5, 1, covers="Water in living things and daily life, what water dissolves, its forms, the water cycle, scarcity and conservation.",
   game=("Lake of Two Villages", "You share one lake of 30 water tokens. Each round, both secretly choose to take 2 (careful) or 5 (greedy) tokens for your fields; then a rain card refills 0–6. If the lake ever empties, both villages lose. Most harvest when the season ends, without emptying the lake, wins. Talk about why sharing rules matter."),
   exp=["What dissolves? Salt, sugar, sand, oil, haldi, chalk in water. Stir, wait, observe.", "Hidden water: weigh a cucumber slice, dry it in the sun for 2 days, weigh again."],
   act=["Trace your home's water from its source to your tap.", "Compare how much water different crops need (rice vs millets)."],
   proj=("Water Heroes Model", "Research a traditional system (stepwell, johad, kund, eri) and build a working rain-harvesting model.", "A model and a 3-minute talk"),
   read=["The Water Princess, Susan Verde", "A River, Marc Martin"],
   links=["Santoor Ch 3: The Rainbow", "Veena Ch 12: Ganga ki Kahani", "Maths Mela Ch 8: Weight and Capacity"], dk=["B8", "C12"])
ch(5, 2, covers="A river's journey from its source to the sea: source, tributary, delta, mouth; fast narrow upper course and slow wide lower course; life along rivers.",
   game=("River Run", "A board from glacier to sea. Roll to move; tributary squares speed you up, dam squares make you wait, pollution squares push you back, the delta is the finish. Each square carries a real fact about the Ganga, Brahmaputra, Narmada or Kaveri."),
   exp=["Stream table: a tray of damp sand on a slope; trickle water from a bottle at the top. Watch channels, bends and a delta form. Try steep vs gentle slopes."],
   act=["Trace a river on a map from source to mouth and mark the cities on it.", "Collect river stories, such as the legend of the Kaveri."],
   proj=("River Model", "Build a sand or clay river with labelled source, tributaries and delta, and a one-page profile of a river near you.", "A 3D river model"),
   read=["Angry River, Ruskin Bond", "A River, Marc Martin"],
   links=["Veena Ch 12: Ganga ki Kahani", "Maths Mela Ch 14: Maps and Locations"], dk=["B8"])
ch(5, 3, covers="How food changes: cooking, spoiling, fermenting and digesting (align with the book's focus).",
   game=("Food Detective", "Mystery cards give clues (smells sour, bubbles appeared, fuzzy spots, turned sweet when chewed). Use the fewest clues to name what happened: fermentation, spoilage, cooking or digestion. Fewer clues used, more points."),
   exp=["Chew plain roti for 2 minutes: when does it turn sweet?", "Idli batter: keep one bowl warm and one in the fridge overnight. Which rises?", "Milk to curd at room temperature vs in the fridge."],
   act=["Ask grandparents how food was preserved without a fridge (sun-drying, pickling).", "Watch a fruit go brown after cutting; does lemon juice stop it?"],
   proj=("Fermentation Lab", "Over one week make curd, idli batter and kanji; photograph and log changes daily.", "Foods to eat and a lab notebook"),
   read=["Bread, Bread, Bread, Ann Morris"],
   links=["Maths Mela Ch 6: The Dairy Farm", "Maths Mela Ch 9: Coconut Farm"], dk=["C11", "B3"])
ch(5, 4, covers="What makes a learning place happy: people, rules, cleanliness, inclusion. For homeschoolers: your own learning community.",
   game=("Dream School Draft", "Draft feature cards (library, garden, ramps and lifts, sign-language teacher, sports ground, kitchen) within a budget. Each pick must be justified: who does it help? The opponent can veto once."),
   exp=["Light and sound check: measure how bright and how noisy your learning corner is at different times (use a phone light/sound meter or rate 1–5)."],
   act=["Interview a friend who goes to school: what makes it happy or hard?", "Agree a set of rules for your homeschool group or siblings."],
   proj=("Learning-Space Makeover", "Redesign the home learning corner and write a charter for your learning group.", "A rearranged corner and a signed charter"),
   read=["Chuskit Goes to School, Sujatha Padmanabhan", "The Day You Begin, Jacqueline Woodson"],
   links=["Veena Ch 7: Mera Bachpan"], dk=["B2"])
ch(5, 5, covers="India's diversity of languages, foods, dances, festivals and crafts, and what unites us.",
   game=("India Quartets", "Each state has 4 cards: language, dance, food, monument. Ask your opponent for a card ('Do you have Assam's dance?'). Collect all four of a state to lay down a quartet. Most quartets wins."),
   exp=["Language sounds: record 'hello' and 'thank you' in 10 Indian languages. Which share words?"],
   act=["Fill a blank India map with states and one fact each.", "Cook one dish from a state you've never visited."],
   proj=("State Exchange", "Video-call or write to a child in another state; make a fact book about each other's state.", "A two-state fact book"),
   read=["A Gift for Amma: Market Day in India, Meera Sriram", "Amma, Take Me to… series, Bhakti Mathur"],
   links=["Veena Ch 11: Hamare ye Kalamandir", "Veena Ch 8: Kaziranga Rashtriya Udyan ki Yatra"], dk=["B2"])
ch(5, 6, covers="Unusual landscapes, rare wildlife and traditions in India (e.g. deserts, mangroves, floating lakes, cold deserts).",
   game=("Where in India?", "A travel guessing game: the opponent reads clues one at a time (floating islands of grass; a white salt desert; mangroves with tigers; bridges grown from tree roots). Guess with fewer clues to score more. Then swap."),
   exp=["Salt from the sea: dissolve salt in water in a shallow plate and leave it in the sun. What's left after 3 days? (This is how salt pans work.)", "Floating island: does a grass mat on a sponge float? What keeps Loktak's phumdis afloat?"],
   act=["Plan a trip to one unique place: route, budget, packing list.", "Find the animals found only in that place."],
   proj=("Unique-Place Diorama", "A shoebox diorama of one place plus a one-minute guide video.", "A diorama and a video"),
   read=["StoryWeaver (Pratham Books): search 'Sundarbans' or 'Ladakh'"],
   links=["Veena Ch 8: Kaziranga Rashtriya Udyan ki Yatra", "Maths Mela Ch 5: Far and Near", "Maths Mela Ch 14: Maps and Locations"], dk=["B8", "B4"])
ch(5, 7, covers="Forms of energy, where it comes from (food, fuel, sun, electricity), how devices use it, saving energy.",
   game=("Energy Chains", "Cards show energy steps (Sun, grass, cow, milk, my muscles, bicycle, dynamo, bulb). Build valid chains where each card's energy turns into the next. Longest chain wins; the opponent can challenge any link."),
   exp=["Pizza-box solar oven: foil, black paper and cling film. Can it melt chocolate? Measure with a thermometer if you have one.", "Rubber-band car: wind more turns, travel further?"],
   act=["Home energy audit: lights and fans left on, the meter reading each day for a week.", "Find 5 ways energy changes form in the kitchen."],
   proj=("Solar Cooker Challenge", "Build a solar cooker, test it over 3 days, and cook something simple.", "A working cooker and a temperature log"),
   read=["The Boy Who Harnessed the Wind (picture-book edition), William Kamkwamba & Bryan Mealer", "Energy Island, Allan Drummond"],
   links=["Maths Mela Ch 12: Racing Seconds"], dk=["C12", "B6"])
ch(5, 8, covers="Fibres (cotton, silk, wool, jute, synthetic), spinning, weaving and dyeing, khadi, how clothes are made.",
   game=("Fibre Detective", "Mystery fabric scraps in envelopes with clue cards (soaks water fast, comes from a caterpillar, shines, keeps sheep warm). Feel, test with a drop of water, and name the fibre."),
   exp=["Water test: drop water on cotton, polyester, wool and silk. Which soaks it up?", "Natural dyes: boil haldi, onion skins or beetroot (adult) and dye white cloth strips."],
   act=["Learn the story of the charkha and khadi.", "Check clothing labels at home: what are your clothes made of?"],
   proj=("Dye and Weave", "Dye cloth or yarn with natural dyes and weave a small mat or bookmark on a cardboard loom.", "A woven piece"),
   read=["Charlie Needs a Cloak, Tomie dePaola"],
   links=["Maths Mela Ch 11: Grandmother's Quilt", "Santoor Ch 10: Glass Bangles"], dk=["A4"])
ch(5, 9, covers="Cycles in nature: day and night, seasons, flowering and fruiting times, migration, body clocks.",
   game=("Nature's Clock", "Event cards (the koel calls, mango trees flower, monsoon arrives, Amur falcons pass through Nagaland, owls hunt) go onto a day wheel or a year wheel. Place each correctly and explain why then; most points wins."),
   exp=["Four o'clock flower (gulbas): note when its flowers open each day for a week.", "Your body clock: rate your energy every 2 hours for 3 days. When are you sharpest?"],
   act=["Visit one tree every week and record leaves, flowers, fruit and visitors.", "Mark shadow length at noon each week."],
   proj=("Year Wheel", "A big circular calendar of local nature events, plus 4 weeks of tree and bird observations.", "A year-wheel poster"),
   read=["The Reasons for Seasons, Gail Gibbons", "A Butterfly Is Patient, Dianna Hutts Aston"],
   links=["Veena Ch 3: Chaand ka Kurta", "Veena Ch 1: Kiran", "Maths Mela Ch 12: Racing Seconds"], dk=["B5", "B4"])
ch(5, 10, covers="Earth as a shared home for all living things, resources, climate, pollution and caring for the planet.",
   game=("Planet Keepers", "A cooperative game. Shared Earth-health tokens start at 20. Each round flip a world event (forest fire, new factory, tree-planting drive) and each player picks one action card. Explain your choice to play it. Finish 10 rounds with Earth-health above 10 to win together."),
   exp=["Greenhouse in a jar: two thermometers in the sun, one covered by a glass jar. Compare after 30 minutes.", "Dust catcher: a Vaseline card outside for 2 days; look with a magnifier."],
   act=["A simple family footprint check: travel, electricity, food waste.", "Debate: should we stop using plastic completely?"],
   proj=("Earth Pledge Campaign", "Choose one family change, measure it for 4 weeks, and present results to neighbours or your learning group.", "A campaign poster and a results chart"),
   read=["Earth! My First 4.54 Billion Years, Stacy McAnulty", "The Curious Garden, Peter Brown", "Wangari's Trees of Peace, Jeanette Winter"],
   links=["Veena Ch 10: Teen Machhliyan", "Maths Mela Ch 15: Data Through Pictures"], dk=["B9", "B1"])
